// Arduino PCA9685 Pan-Tilt Servo Example
#include <Wire.h>
#include <Adafruit_PWMServoDriver.h>

Adafruit_PWMServoDriver pwm = Adafruit_PWMServoDriver(0x40);

void setup() {
  pwm.begin();
  pwm.setPWMFreq(50); // Servo frequency 50Hz
}

void loop() {
  // Pan axis (Channel 0) to neutral 90 deg (~307 pulse)
  pwm.setPWM(0, 0, 307);
  // Tilt axis (Channel 1) to neutral 90 deg
  pwm.setPWM(1, 0, 307);
  delay(1000);
}

