// ToF Packet Parser
void parseToFData(uint8_t buf[]) {
  if(buf[0] == 0x57 && buf[1] == 0x00) {
    uint32_t distance_mm = buf[4] | (buf[5] << 8) | (buf[6] << 16);
    Serial.print("Distance: "); Serial.print(distance_mm); Serial.println(" mm");
  }
}

// HC-SR04 Ultrasonic Distance Measurement
long duration;
int distance;
void setup() {
  pinMode(8, OUTPUT); // Trig
  pinMode(9, INPUT);  // Echo
  Serial.begin(9600);
}
void loop() {
  digitalWrite(8, LOW); delayMicroseconds(2);
  digitalWrite(8, HIGH); delayMicroseconds(10);
  digitalWrite(8, LOW);
  duration = pulseIn(9, HIGH);
  distance = duration * 0.034 / 2;
  Serial.print("Distance: "); Serial.print(distance); Serial.println(" cm");
  delay(200);
}

// Arduino MT8870 Decoder Code
void setup() {
  for(int i=2; i<=6; i++) pinMode(i, INPUT);
  Serial.begin(9600);
}
void loop() {
  if(digitalRead(6) == HIGH) { // StD valid signal
    int code = (digitalRead(5)<<3) | (digitalRead(4)<<2) | (digitalRead(3)<<1) | digitalRead(2);
    Serial.print("DTMF Key Code: "); Serial.println(code);
    delay(250);
  }
}

void setup() {
  pinMode(2, INPUT);
  pinMode(13, OUTPUT);
}
void loop() {
  if (digitalRead(2) == LOW) { // Obstacle detected
    digitalWrite(13, HIGH);
  } else {
    digitalWrite(13, LOW);
  }
}

void setup() {
  pinMode(2, OUTPUT); // STEP
  pinMode(3, OUTPUT); // DIR
}
void loop() {
  digitalWrite(3, HIGH); // Forward
  for(int i=0; i<200; i++) { // 1 Revolution (200 steps)
    digitalWrite(2, HIGH); delayMicroseconds(800);
    digitalWrite(2, LOW);  delayMicroseconds(800);
  }
  delay(1000);
}

volatile unsigned int pulses = 0;
void countPulse() { pulses++; }
void setup() {
  attachInterrupt(digitalPinToInterrupt(2), countPulse, RISING);
  Serial.begin(9600);
}
void loop() {
  delay(1000);
  Serial.print("Pulses per sec: "); Serial.println(pulses);
  pulses = 0;
}

// Arduino RF24 Transmit Code
#include <SPI.h>
#include <RF24.h>
RF24 radio(9, 10);
const byte address[6] = "00001";
void setup() {
  radio.begin();
  radio.openWritingPipe(address);
  radio.stopListening();
}
void loop() {
  const char text[] = "Hello Robot";
  radio.write(&text, sizeof(text));
  delay(1000);
}

